css:
.ds-shell { min-height:100dvh; }
.ds-header { max-width:1440px; margin:0 auto; min-height:88px; padding:20px 48px; display:flex; align-items:center; justify-content:space-between; gap:24px; }
.ds-brand { padding:0; border:0; background:none; font-family:inherit; cursor:pointer; display:inline-flex; align-items:center; gap:10px; min-height:44px; color:var(--color-ink); font-size:17px; font-weight:600; line-height:1.3; text-decoration:none; }
.ds-innerHeader { min-height:72px; padding-block:12px; }
.ds-backIcon { flex-shrink:0; color:var(--color-ink-soft); transition:transform 140ms ease-out,color 140ms ease; }
@media(hover:hover) and (pointer:fine) {
  .ds-brand:hover .ds-backIcon { color:var(--color-ink); transform:translateX(-2px); }
}
.ds-brand:focus-visible .ds-backIcon { color:var(--color-ink); }
@media(prefers-reduced-motion:reduce) {
  .ds-backIcon { transition:none; }
  .ds-brand:hover .ds-backIcon { transform:none; }
}
.ds-content { outline:none; min-width:0; }
.ds-skip { position:fixed; z-index:1000; top:8px; left:20px; transform:translateY(-160%); padding:10px 16px; background:var(--color-ink); color:var(--color-paper); border-radius:4px; }
.ds-skip:focus { transform:none; }
@media(max-width:1100px) { .ds-header { padding-inline:24px; } }
@media(max-width:639px) { .ds-header { min-height:72px; padding:12px 20px; } .ds-brand { font-size:16px; } }

.ds-brand:focus-visible { outline:2px solid var(--color-ink); outline-offset:4px; }

.ds-brand h1 { margin:0; font:inherit; letter-spacing:0; }

.ds-heading { margin:0; font:inherit; }

.ds-identity { display:flex; align-items:center; gap:8px; }

/* A single text layer carries the selected work into its page heading. */
.ds-travelTitle { position:fixed; z-index:100; margin:0; padding:0; pointer-events:none; transform-origin:0 0; white-space:nowrap; }
